const txNow = `-- name: TxNow :one
SELECT now()::timestamptz AS now
`

// The transaction's clock: the clock of every timestamp the chat writes store.
func (q *Queries) TxNow(ctx context.Context) (time.Time, error) {
	row := q.db.QueryRow(ctx, txNow)
	var now time.Time
	err := row.Scan(&now)
	return now, err
}

const upsertReadState = `-- name: UpsertReadState :one
INSERT INTO chat_read_state (chat_id, user_id, last_read_at)
VALUES ($1::uuid, $2::uuid,
        least(coalesce($3::timestamptz, now()), now()))
ON CONFLICT (chat_id, user_id) DO UPDATE
SET last_read_at = greatest(chat_read_state.last_read_at, EXCLUDED.last_read_at)
RETURNING last_read_at
`

type UpsertReadStateParams struct {
	ChatID     uuid.UUID
	UserID     uuid.UUID
	LastReadAt *time.Time
}

// POST /v1/chats/{id}/read (and a sender's own message): the read state only moves forward, and never past the
// database clock (the clock of every message's created_at; no lastReadAt = now). Returns the stored value.
func (q *Queries) UpsertReadState(ctx context.Context, arg UpsertReadStateParams) (time.Time, error) {
	row := q.db.QueryRow(ctx, upsertReadState, arg.ChatID, arg.UserID, arg.LastReadAt)
	var last_read_at time.Time
	err := row.Scan(&last_read_at)
	return last_read_at, err
}

const userRefs = `-- name: UserRefs :many
SELECT id, coalesce(legacy_auth_uid, id::text)::text AS ref FROM users WHERE id = ANY ($1::uuid[])
`

type UserRefsRow struct {
	ID  uuid.UUID
	Ref string
}

// The ids the 3.x app and the legacy web know for users (Firebase uid = legacy_auth_uid, else the uuid the bridge
// gives a user born in Go): the senderId, assignedAdminId, lastMessageBy and lastReadByAdmin keys of the write-back.
func (q *Queries) UserRefs(ctx context.Context, ids []uuid.UUID) ([]UserRefsRow, error) {
	rows, err := q.db.Query(ctx, userRefs, ids)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []UserRefsRow{}
	for rows.Next() {
		var i UserRefsRow
		if err := rows.Scan(&i.ID, &i.Ref); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
